from .message_handling import (SMessageHeader,
                               RequestMessage, ResponseMessage, Query, BasicQueryManager,
                               register_message, u32, u8)

from ..commons import LOGGER


ADDRESS_PROTECTED_NYQUIST = 0x0000FFFF
ADDRESS_PROTECTED_KEPLER = 0x0008E000
BYTES_IN_WORD = 4


@register_message
class BrowserDspMemoryReq(RequestMessage):
    id = 0x1beb
    _fields_ = [
        ('header', SMessageHeader),
        ('writeData', u32),
        ('dataCount', u32),
        ('dspDataAddress', u32),
        ('dspData', u32 * 1)
    ]


@register_message
class BrowserDspMemoryAck(ResponseMessage):
    id = 0x1bec
    _fields_ = [
        ('header', SMessageHeader),
        ('status', u32),
        ('dataCount', u32),
        ('dspDataAddress', u32),
        ('dspData', u8 * 4)
    ]


@register_message
class MemDumperAgentSetupReq(RequestMessage):
    id = 0x7050
    _fields_ = [
        ('header', SMessageHeader),
        ('empty', u32)
    ]


class BrowserDspMemoryQuery(Query):
    def __init__(self, req, resp):
        super(BrowserDspMemoryQuery, self).__init__(req, resp)
        self.status = None

    def fill_req_msg(self, address, data, count):
        # type (int, int, int) - > None
        self.req_msg.dspDataAddress = address
        self.req_msg.writeData = 1
        self.req_msg.dataCount = count
        self.req_msg.dspData[0] = data

    def _handle_response(self,):
        self.status = self.resp_msg.status
        if self.status != 0:
            LOGGER.warn('DSP crash error (status {}) '.format(self.status))


class DspMemoryInterface(object):
    def __init__(self, connection):
        self.connection = connection

    def write_memory(self, board, cpu, address, data, count):
        # type: (int, int, int, int, int) -> None
        query = BrowserDspMemoryQuery(BrowserDspMemoryReq(board, cpu), BrowserDspMemoryAck())
        query.fill_req_msg(address, data, count)
        qm = BasicQueryManager(query, self.connection)
        qm.send_request_and_wait_for_response()  # probably no response here, so maybe just send()?
